package com.edgeos.launcher;
import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
public final class Ui { private Ui(){} public static int dp(Context c,int n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);} public static GradientDrawable bg(int color,float r){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(r);return g;} public static TextView text(Context c,String s,float size,int color){TextView t=new TextView(c);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);return t;} public static Button pill(Context c,String s){Button b=new Button(c);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(bg(0x66303038,80));return b;} }
